package com.sky.handler;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

import com.sky.result.Result;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.junit.jupiter.MockitoExtension;

@ExtendWith(MockitoExtension.class)
class GlobalExceptionHandlerTest {

    @InjectMocks
    private GlobalExceptionHandler globalExceptionHandler;

    @Test
    @DisplayName("正向测试：当抛出 NumberFormatException 时，异常处理器应返回包含正确错误消息的错误结果")
    void testHandleNumberFormatException_WithMessage() {
        // Arrange
        NumberFormatException exception = new NumberFormatException("For input string: \"abc\"");

        // Act
        Result<String> result = globalExceptionHandler.exceptionHandler(exception);

        // Assert
        assertNotNull(result);
        assertEquals("请求参数格式错误", result.getMsg());
        assertNotEquals(1, result.getCode(), "错误结果的code不应为1（成功）");
    }

    @Test
    @DisplayName("边界测试：当 NumberFormatException 的消息为 null 时，异常处理器应仍返回错误结果")
    void testHandleNumberFormatException_WithNullMessage() {
        // Arrange - 构造一个消息为null的NumberFormatException
        NumberFormatException exception = new NumberFormatException(null);

        // Act
        Result<String> result = globalExceptionHandler.exceptionHandler(exception);

        // Assert - 验证方法执行正常，不抛出异常，且返回错误结果
        assertDoesNotThrow(() -> globalExceptionHandler.exceptionHandler(exception));
        assertNotNull(result);
        assertEquals("请求参数格式错误", result.getMsg());
    }

    @Test
    @DisplayName("正向测试：验证异常处理器返回的 Result 对象状态为错误")
    void testHandleNumberFormatException_ReturnsErrorResultStatus() {
        // Arrange
        NumberFormatException exception = new NumberFormatException("test error");

        // Act
        Result<String> result = globalExceptionHandler.exceptionHandler(exception);

        // Assert - 验证返回结果指示错误状态
        assertNotNull(result);
        assertNotEquals(1, result.getCode(), "错误结果的code不应为1（成功）");
        assertNotNull(result.getMsg(), "错误消息不应为null");
        assertFalse(result.getMsg().isEmpty(), "错误消息不应为空字符串");
    }
}
